  const vein = Math.abs(Math.sin(sx*0.08+Math.sin(sy*0.06+t)*2))*Math.abs(Math.sin(sy*0.07+Math.cos(sx*0.05-t)*2))*0.4;
  const blend = rd1*0.45 + rd2*0.25 + cell*0.15 + vein*0.1 + coupling*0.05;
  const v = blend*0.5+0.5;
  const pal = [[5,12,52],[12,42,88],[18,82,115],[25,128,135],[45,158,120],[140,175,85],[195,185,65],[215,145,55],[195,95,65],[160,50,75],[95,28,65],[40,18,55],[5,12,52]];
